const input = $input.first().json;

const cadenceId = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
  const r = Math.random() * 16 | 0;
  const v = c === "x" ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

const steps = [
  { step: 1, kind: 'nudge', offsetHours: 5, message: 'Oi! Passando pra saber se ainda faz sentido a gente continuar essa conversa. Fico a disposicao.' },
  { step: 2, kind: 'nudge', offsetHours: 12, message: 'Oi, tudo bem? Ainda estou por aqui caso queira retomar.' },
  { step: 3, kind: 'nudge', offsetHours: 24, message: 'So mais um lembrete - se precisar de algo, e so chamar.' },
  { step: 4, kind: 'nudge', offsetHours: 36, message: 'Ainda por aqui caso queira continuar - e so me chamar quando quiser.' },
  { step: 5, kind: 'ultimatum', offsetHours: 48, message: 'Como nao tivemos retorno, vou encerrar esse atendimento por aqui. Quando quiser continuar, e so me chamar de novo.' }
];

const now = new Date();

return steps.map(s => {
  const scheduledFor = new Date(now.getTime() + s.offsetHours * 60 * 60 * 1000);
  return {
    json: {
      tenant_id: input.tenant_id,
      conversation_id: input.conversation_id,
      cadence_id: cadenceId,
      step: s.step,
      kind: s.kind,
      reason: input.resumo,
      message: s.message,
      scheduled_for: scheduledFor.toISOString()
    }
  };
});

const items = $input.all();
const cadenceId = items.length ? items[0].json.cadence_id : null;
return [{ json: { success: true, cadence_id: cadenceId, etapas_agendadas: items.length, detail: 'Cadencia de follow-up agendada: 4 lembretes (5h/12h/24h/36h sem resposta) + 1 mensagem final de encerramento (48h), cancelada automaticamente se o cliente responder.' } }];
